const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const W=960,H=640,GROUND=594, BALL_R=18;
const levels=[
 {name:'The First Nudge',hint:'A long, gentle ramp can carry the ball all the way across.',start:[145,168],goal:[790,565],ground:GROUND,lines:[],color:'#ff8277'},
 {name:'Over the Hump',hint:'Build a bridge over the wall. The ball can roll right over the top.',start:[145,185],goal:[795,565],ground:GROUND,lines:[[[495,302],[495,554]]],color:'#ff8277'},
 {name:'The Little Valley',hint:'A line through the valley can lift the ball back out the other side.',start:[145,155],goal:[805,565],ground:GROUND,lines:[[[310,505],[420,405]],[[420,405],[530,505]]],color:'#ff8277'},
 {name:'Mind the Gap',hint:'Make a bridge across the gap, or give the ball a little launch.',start:[145,430],goal:[790,565],ground:GROUND,lines:[[[300,520],[300,594]],[[590,520],[590,594]]],color:'#ff8277'},
 {name:'Up the Steps',hint:'A carefully drawn slope can turn a fall into a climb.',start:[160,170],goal:[800,565],ground:GROUND,lines:[[[430,470],[430,594]],[[610,370],[610,594]]],color:'#ff8277'},
 {name:'The Grand Finale',hint:'There is more than one way through. Let gravity do the hard work!',start:[125,190],goal:[825,565],ground:GROUND,lines:[[[310,445],[385,365]],[[385,365],[460,445]],[[575,365],[650,445]]],color:'#ff8277'}
];
let current=0,strokes=[],ball=null,won=false,drawState=null,lastTime=0,accumulator=0,toastTimer=0,hintShown=false;
let completed=new Set(JSON.parse(localStorage.getItem('little-nudge-completed')||'[]'));
let soundOn=true,audioCtx=null,particles=[];
const colors={ink:'#273149',blue:'#697ff2',mint:'#68c99c',coral:'#ff8176'};
function makeBall(){const l=levels[current];ball={x:l.start[0],y:l.start[1],vx:0,vy:0,r:BALL_R};}
function setLevel(i){current=(i+levels.length)%levels.length;strokes=[];won=false;hintShown=false;particles=[];makeBall();document.getElementById('win-modal').classList.remove('show');document.getElementById('level-title').innerHTML=String(current+1).padStart(2,'0')+' &nbsp; '+levels[current].name;document.getElementById('hint-text').textContent='Draw a ramp to guide the ball to the goal.';drawSidebar();}
function reset(){strokes=[];won=false;hintShown=false;particles=[];makeBall();document.getElementById('win-modal').classList.remove('show');document.getElementById('hint-text').textContent='Draw a ramp to guide the ball to the goal.';}
function drawSidebar(){const list=document.getElementById('level-list');list.innerHTML='';levels.forEach((l,i)=>{const item=document.createElement('button');item.className='level-card'+(i===current?' selected':'')+(completed.has(i)?' complete':'');item.setAttribute('aria-label','Puzzle '+(i+1)+': '+l.name);item.innerHTML='<span class="level-number">'+(completed.has(i)?'✓':String(i+1).padStart(2,'0'))+'</span><span class="level-info"><span class="level-name">'+l.name+'</span><span class="level-desc">Puzzle '+String(i+1).padStart(2,'0')+'</span></span><span class="level-state">'+(completed.has(i)?'★':'')+'</span>';item.addEventListener('click',()=>setLevel(i));list.appendChild(item);const dot=document.createElement('span');dot.className='level-dot'+(i===current?' active':'');document.getElementById('level-dots').appendChild(dot);});document.getElementById('level-dots').innerHTML='';levels.forEach((_,i)=>{const d=document.createElement('span');d.className='level-dot'+(i===current?' active':'');document.getElementById('level-dots').appendChild(d);});const count=completed.size;document.getElementById('score-pill').innerHTML='✦ &nbsp;'+count+' / '+levels.length+' solved';document.getElementById('progress-count').textContent=count+' of '+levels.length;document.getElementById('progress-bar').style.width=(count/levels.length*100)+'%';document.getElementById('progress-percent').textContent=Math.round(count/levels.length*100)+'%';}
function resize(){const rect=canvas.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);}
window.addEventListener('resize',resize);resize();
function pointerPos(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width*W,y:(e.clientY-r.top)/r.height*H};}
canvas.addEventListener('pointerdown',e=>{if(won)return;e.preventDefault();canvas.setPointerCapture(e.pointerId);const p=pointerPos(e);drawState={points:[p]};});
canvas.addEventListener('pointermove',e=>{if(!drawState)return;const p=pointerPos(e),pts=drawState.points,last=pts[pts.length-1];if(Math.hypot(p.x-last.x,p.y-last.y)>8){if(pts.length<220)pts.push(p);}});
function finishDraw(){if(!drawState)return;const pts=drawState.points;drawState=null;if(pts.length===1){const p=pts[0];pts.push({x:p.x+1,y:p.y+1});}if(pts.length>1)strokes.push(pts);}
canvas.addEventListener('pointerup',finishDraw);canvas.addEventListener('pointercancel',finishDraw);
function closestPoint(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,len=dx*dx+dy*dy;let t=len?((p.x-a.x)*dx+(p.y-a.y)*dy)/len:0;t=Math.max(0,Math.min(1,t));return{x:a.x+t*dx,y:a.y+t*dy};}
function allSegments(){const out=[];for(const pair of levels[current].lines)out.push({a:{x:pair[0][0],y:pair[0][1]},b:{x:pair[1][0],y:pair[1][1]},r:5});for(const pts of strokes)for(let i=1;i<pts.length;i++)out.push({a:pts[i-1],b:pts[i],r:5});return out;}
let segments=[];
function physics(dt){if(!ball||won)return;const sub=3,step=dt/sub;for(let s=0;s<sub;s++){ball.vy+=1080*step;ball.vx*=Math.pow(.999,step*60);ball.vy*=Math.pow(.999,step*60);ball.x+=ball.vx*step;ball.y+=ball.vy*step;
  for(let pass=0;pass<3;pass++){
   if(ball.x<ball.r){ball.x=ball.r;ball.vx=Math.abs(ball.vx)*.28;}if(ball.x>W-ball.r){ball.x=W-ball.r;ball.vx=-Math.abs(ball.vx)*.28;}if(ball.y<ball.r){ball.y=ball.r;ball.vy=Math.abs(ball.vy)*.25;}
   if(ball.y>levels[current].ground-ball.r){ball.y=levels[current].ground-ball.r;if(ball.vy>0)ball.vy*=-.2;ball.vx*=.985;if(Math.abs(ball.vy)<18)ball.vy=0;}
   for(const seg of segments){const q=closestPoint(ball,seg.a,seg.b),dx=ball.x-q.x,dy=ball.y-q.y,d=Math.hypot(dx,dy),min=ball.r+seg.r;if(d<min){let nx,ny;if(d<.001){const l=Math.hypot(seg.b.x-seg.a.x,seg.b.y-seg.a.y)||1;nx=-(seg.b.y-seg.a.y)/l;ny=(seg.b.x-seg.a.x)/l;}else{nx=dx/d;ny=dy/d;}ball.x+=nx*(min-d+.02);ball.y+=ny*(min-d+.02);const vn=ball.vx*nx+ball.vy*ny;if(vn<0){ball.vx-=1.32*vn*nx;ball.vy-=1.32*vn*ny;const tx=-ny,ty=nx,vt=ball.vx*tx+ball.vy*ty;ball.vx-=vt*tx*.012;ball.vy-=vt*ty*.012;}}}
  }
 }
 const g=levels[current].goal;if(Math.hypot(ball.x-g[0],ball.y-g[1])<20){completeLevel();}
}
function completeLevel(){if(won)return;won=true;completed.add(current);localStorage.setItem('little-nudge-completed',JSON.stringify([...completed]));drawSidebar();playWin();const m=document.getElementById('win-modal');m.classList.add('show');particles=Array.from({length:48},()=>({x:ball.x,y:ball.y,vx:(Math.random()-.5)*420,vy:-Math.random()*450-80,life:1,color:['#7587ff','#ffc963','#69d2a3','#ff8378'][Math.floor(Math.random()*4)]}));}
function playWin(){if(!soundOn)return;try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();const now=audioCtx.currentTime;[523,659,784].forEach((f,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.frequency.value=f;o.type='sine';g.gain.setValueAtTime(.0001,now+i*.09);g.gain.exponentialRampToValueAtTime(.12,now+i*.09+.02);g.gain.exponentialRampToValueAtTime(.0001,now+i*.09+.3);o.connect(g);g.connect(audioCtx.destination);o.start(now+i*.09);o.stop(now+i*.09+.32);});}catch(e){}}
function roundRect(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r);}

function draw(){ctx.clearRect(0,0,W,H);const bg=ctx.createLinearGradient(0,0,0,H);bg.addColorStop(0,'#fbfcff');bg.addColorStop(1,'#f8faff');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
 // subtle dot field
 ctx.fillStyle='#e7eaf3';for(let x=28;x<W;x+=32)for(let y=28;y<GROUND;y+=32){ctx.beginPath();ctx.arc(x,y,1.15,0,Math.PI*2);ctx.fill();}
 // ground
 ctx.fillStyle='#edf0f7';ctx.fillRect(0,GROUND,W,H-GROUND);ctx.fillStyle='#dde2ee';ctx.fillRect(0,GROUND,W,2);
 // goal marker + cup
 const goal=levels[current].goal;ctx.save();ctx.translate(goal[0],goal[1]);ctx.strokeStyle='#65c79b';ctx.lineWidth=7;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-26,-20);ctx.lineTo(-26,8);ctx.quadraticCurveTo(0,32,26,8);ctx.lineTo(26,-20);ctx.stroke();ctx.fillStyle='#e6f8ef';ctx.beginPath();ctx.arc(0,0,27,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#65c79b';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-19,-18);ctx.lineTo(-19,6);ctx.quadraticCurveTo(0,24,19,6);ctx.lineTo(19,-18);ctx.stroke();ctx.fillStyle='#58bc8b';ctx.beginPath();ctx.arc(0,0,4,0,Math.PI*2);ctx.fill();ctx.restore();
 // static level obstacles
 for(const pair of levels[current].lines){drawPhysicalLine({x:pair[0][0],y:pair[0][1]},{x:pair[1][0],y:pair[1][1]},true);}
 // user lines
 for(const pts of strokes)for(let i=1;i<pts.length;i++)drawPhysicalLine(pts[i-1],pts[i],false);
 if(drawState){for(let i=1;i<drawState.points.length;i++)drawPhysicalLine(drawState.points[i-1],drawState.points[i],false,true);}
 // start marker
 const st=levels[current].start;ctx.save();ctx.globalAlpha=.6;ctx.strokeStyle='#94a0b7';ctx.setLineDash([5,6]);ctx.lineWidth=2;ctx.beginPath();ctx.arc(st[0],st[1],28,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.restore();
 // ball shadow
 if(ball){ctx.save();ctx.fillStyle='#28365318';ctx.beginPath();ctx.ellipse(ball.x+3,GROUND-2,19,5,0,0,Math.PI*2);ctx.fill();ctx.restore();drawBall();}
 for(const p of particles){ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,4,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;
}
function drawPhysicalLine(a,b,staticLine,dashed=false){const dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy);if(len<.1)return;ctx.save();ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle=dashed?'#8191ed':staticLine?'#c9cfdf':'#7184ef';ctx.lineWidth=staticLine?13:11;if(dashed)ctx.setLineDash([8,7]);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle=staticLine?'#eef0f6':'#aebafb';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();if(!staticLine&&!dashed){ctx.fillStyle='#7184ef';for(const p of [a,b]){ctx.beginPath();ctx.arc(p.x,p.y,5.5,0,Math.PI*2);ctx.fill();}}ctx.restore();}
function drawBall(){const b=ball;ctx.save();const grad=ctx.createRadialGradient(b.x-6,b.y-7,2,b.x,b.y,b.r);grad.addColorStop(0,'#ffb3a5');grad.addColorStop(.55,'#ff8176');grad.addColorStop(1,'#e96a62');ctx.fillStyle=grad;ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#df6d65';ctx.lineWidth=1.5;ctx.stroke();ctx.fillStyle='#ffffff9c';ctx.beginPath();ctx.arc(b.x-6,b.y-7,4.2,0,Math.PI*2);ctx.fill();ctx.restore();}
function frame(t){if(!lastTime)lastTime=t;let dt=Math.min((t-lastTime)/1000,.033);lastTime=t;segments=allSegments();physics(dt);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=700*dt;p.life-=dt*.78;}particles=particles.filter(p=>p.life>0);draw();requestAnimationFrame(frame);}requestAnimationFrame(frame);
function undo(){if(strokes.length){strokes.pop();toast('Last line removed');}else toast('Nothing to undo yet');}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1300);}
function showHint(){if(!hintShown){document.getElementById('hint-text').textContent=levels[current].hint;hintShown=true;}else toast(levels[current].hint);}
document.getElementById('undo-btn').addEventListener('click',undo);document.getElementById('reset-btn').addEventListener('click',reset);document.getElementById('hint-btn').addEventListener('click',showHint);
document.getElementById('next-level').addEventListener('click',()=>{let next=(current+1)%levels.length;setLevel(next);});
document.getElementById('sound-btn').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.style.background=soundOn?'white':'#f1f2f7';e.currentTarget.style.opacity=soundOn?'1':'.55';toast(soundOn?'Sound on':'Sound off');});
window.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='z'){undo();}if(e.key.toLowerCase()==='r'){reset();}if(e.key==='ArrowRight')setLevel(current+1);if(e.key==='ArrowLeft')setLevel(current-1);});
setLevel(0);
</script>
</body>
</html>

