function line(a,b,staticLine=false,dash=false){if(Math.hypot(b.x-a.x,b.y-a.y)<.1)return;ctx.save();ctx.lineCap='round';ctx.strokeStyle=dash?'#8191ed':staticLine?'#c9cfdf':'#7184ef';ctx.lineWidth=staticLine?13:11;if(dash)ctx.setLineDash([8,7]);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle=staticLine?'#eef0f6':'#aebafb';ctx.lineWidth=2;ctx.stroke();if(!staticLine&&!dash){ctx.fillStyle='#7184ef';[a,b].forEach(p=>{ctx.beginPath();ctx.arc(p.x,p.y,5.5,0,Math.PI*2);ctx.fill();});}ctx.restore();}
