function frame(t){if(!last)last=t;const dt=Math.min((t-last)/1000,.033);last=t;segments=getSegments();physics(dt);draw();requestAnimationFrame(frame);}function toast(s){let e=document.getElementById('toast');e.textContent=s;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),1250);}document.getElementById('undo-btn').onclick=()=>{if(strokes.length)strokes.pop();else toast('Nothing to undo yet');};document.getElementById('reset-btn').onclick=reset;document.getElementById('hint-btn').onclick=()=>document.getElementById('hint-text').textContent=levels[current].hint;document.getElementById('next-level').onclick=()=>setLevel(current+1);document.getElementById('sound-btn').onclick=e=>{sound=!sound;e.currentTarget.style.opacity=sound?'1':'.5';toast(sound?'Sound on':'Sound off');};window.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='z')document.getElementById('undo-btn').click();if(e.key.toLowerCase()==='r')reset();if(e.key==='ArrowRight')setLevel(current+1);if(e.key==='ArrowLeft')setLevel(current-1);});setLevel(0);requestAnimationFrame(frame);
